package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class DataTableSvgRenderer { public String render(DataTableDiagramSpecV1 s){return render(s,Map.of());} public String render(DataTableDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),w=s.viewport().width()-2*p,h=s.viewport().height()-2*p;var b=new StringBuilder("<rect x=\"").append(p).append("\" y=\"").append(p).append("\" width=\"").append(w).append("\" height=\"").append(h).append("\" fill=\"#FFFFFF\" stroke=\"#000000\"/>");int cols=Math.max(1,s.columnHeaderTemplates().size()),rows=Math.max(1,s.rowHeaderTemplates().size()),cw=w/cols,rh=h/rows;for(var cell:s.cells()){var text=cell.valueKey()!=null&&values.containsKey(cell.valueKey())?values.get(cell.valueKey()).canonicalValue():cell.textTemplate();b.append("<text x=\"").append(p+cell.column()*cw+4).append("\" y=\"").append(p+cell.row()*rh+16).append("\">").append(escape(text)).append("</text>");}for(var cell:s.highlightedCells())b.append("<rect x=\"").append(p+cell.column()*cw).append("\" y=\"").append(p+cell.row()*rh).append("\" width=\"").append(cw).append("\" height=\"").append(rh).append("\" fill=\"none\" stroke=\"#FF0000\"/>");return b.toString();} private String escape(String x){return x==null?"":x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");} }
